    *,
    reveal: bool,
    name: str | None = None,
    managed: bool | None = None,
    in_sync: bool | None = None,
    configured_code: str | None = None,
    active: bool | None = None,
    enabled: bool | None = None,
    config_entry_id: str | None = None,
    config_entry_title: str | None = None,
) -> dict[str, Any]:
    """Serialize a slot dict, masking the code unless ``reveal`` is True."""
    result: dict[str, Any] = {ATTR_SLOT: slot}
    if name:
        result[CONF_NAME] = name
    if managed is not None:
        result[ATTR_MANAGED] = managed
    if in_sync is not None:
        result[ATTR_IN_SYNC] = in_sync
    if active is not None:
        result[ATTR_ACTIVE] = active
    if enabled is not None:
        result[CONF_ENABLED] = enabled
    if config_entry_id:
        result[ATTR_CONFIG_ENTRY_ID] = config_entry_id
    if config_entry_title:
        result[ATTR_CONFIG_ENTRY_TITLE] = config_entry_title

    # Serialize code (SlotCode sentinels, masking, and length) via shared helper.
    result.update(_slot_code_payload(code, reveal=reveal))

    # Configured code from LCM (desired state) - always include for managed slots
    if configured_code is not None:
        if reveal:
            result[ATTR_CONFIGURED_CODE] = configured_code
        else:
            result[ATTR_CONFIGURED_CODE_LENGTH] = len(configured_code)

    return result


@dataclass
class SlotEntities:
    """Entity IDs for a single slot's LCM entities."""

    slot_num: int
    config_entry_id: str | None = None
    name_entity_id: str | None = None
    pin_entity_id: str | None = None
    enabled_entity_id: str | None = None
    active_entity_id: str | None = None
    event_entity_id: str | None = None

    def all_entity_ids(self) -> list[str]:
        """Return all non-None entity IDs (excluding config_entry_id)."""
        return [
            eid
            for eid in (
                self.name_entity_id,
                self.pin_entity_id,
                self.enabled_entity_id,
                self.active_entity_id,
                self.event_entity_id,
            )
            if eid
        ]


@dataclass
class SlotMetadata:
    """Parsed values for a single slot, derived from LCM entity states."""

    name: str | None = None
    configured_pin: str | None = None
    active: bool | None = None
    enabled: bool | None = None


def _build_slot_entities(
    ent_reg: er.EntityRegistry, entry_id: str, slot_num: int
) -> SlotEntities:
    """
    Build a fully-populated SlotEntities for a given (entry, slot) pair.

    Both the per-lock iterator (``_get_slot_entity_ids``) and the
    per-slot subscription resolver go through this primitive so the
    ``unique_id`` formula and the field list live in exactly one place.
    """

    def _id(domain: str, key: str) -> str | None:
        return ent_reg.async_get_entity_id(
            domain, DOMAIN, _slot_unique_id(entry_id, slot_num, key)
        )

    return SlotEntities(
        slot_num=slot_num,
        config_entry_id=entry_id,
        name_entity_id=_id(TEXT_DOMAIN, CONF_NAME),
        pin_entity_id=_id(TEXT_DOMAIN, CONF_PIN),
        enabled_entity_id=_id(SWITCH_DOMAIN, CONF_ENABLED),
        active_entity_id=_id(BINARY_SENSOR_DOMAIN, ATTR_ACTIVE),
        event_entity_id=_id(EVENT_DOMAIN, EVENT_CREDENTIAL_USED),
    )


def _get_slot_entity_ids(
    hass: HomeAssistant, lock_entity_id: str
) -> dict[int, SlotEntities]:
    """Return a dict of slot number to SlotEntities for every slot LCM manages on a lock."""
    ent_reg = er.async_get(hass)
    return {
        slot_int: _build_slot_entities(ent_reg, entry.entry_id, slot_int)
        for entry, config in entries_configuring(hass, lock_entity_id)
        for slot_int in config.slot_numbers
    }


def _get_slot_metadata(
    hass: HomeAssistant, slot_entity_ids: dict[int, SlotEntities]
) -> dict[int, SlotMetadata]:
    """
    Derive SlotMetadata for each slot from pre-resolved SlotEntities.

    Callers already need ``slot_entity_ids`` for other purposes, so
    passing it in avoids re-walking the entity registry just to rebuild
    the same dict.
    """
    return {
        slot_num: SlotMetadata(
            name=_get_text_state(hass, ids.name_entity_id),
            configured_pin=_get_text_state(hass, ids.pin_entity_id),
            active=_get_bool_state(hass, ids.active_entity_id),
            enabled=_get_bool_state(hass, ids.enabled_entity_id),
        )
        for slot_num, ids in slot_entity_ids.items()
    }


def _in_sync_entity_id(
    ent_reg: er.EntityRegistry, entry_id: str, slot_num: int, lock_entity_id: str
) -> str | None:
    """Resolve the in_sync binary sensor entity id for a (slot, lock) pair."""
    unique_id = f"{entry_id}|{slot_num}|{ATTR_IN_SYNC}|{lock_entity_id}"
    return ent_reg.async_get_entity_id(BINARY_SENSOR_DOMAIN, DOMAIN, unique_id)


def _get_slot_state_entity_ids(hass: HomeAssistant, lock_entity_id: str) -> list[str]:
    """
    Get entity IDs for slot state tracking (enabled, active, name, PIN, in_sync).

    Returns the specific LCM entity IDs whose state changes should trigger
    websocket subscription updates for this lock's slots. The in_sync sensor is
    included so the card re-renders when sync status changes -- the unreadable
    code's configured-PIN proxy display is gated on it.
    """
    slot_entities = _get_slot_entity_ids(hass, lock_entity_id)
    ent_reg = er.async_get(hass)
    entity_ids: list[str] = []
    for slot_num, ids in slot_entities.items():
        entity_ids.extend(ids.all_entity_ids())
        if ids.config_entry_id and (
            in_sync_id := _in_sync_entity_id(
                ent_reg, ids.config_entry_id, slot_num, lock_entity_id
            )
        ):
            entity_ids.append(in_sync_id)
    return entity_ids


def _get_lock_friendly_name(hass: HomeAssistant, lock: BaseLock) -> str:
    """Get the friendly name for a lock, using state attributes as primary source."""
    # Prefer the friendly_name from state (what HA displays in the UI)
    if (state := hass.states.get(lock.lock.entity_id)) and (
        friendly_name := state.attributes.get(ATTR_FRIENDLY_NAME)
    ):
        return friendly_name
    # Fall back to entity registry name/original_name
    return lock.display_name


def _serialize_lock_coordinator(
    hass: HomeAssistant, lock: BaseLock, *, reveal: bool = False
) -> dict[str, Any]:
    """Serialize what the lock holds, as its worker knows it."""
    data = lock_codes(hass, lock.lock.entity_id)
    managed_slots = slots_configured_on(hass, lock.lock.entity_id)
    slot_entity_ids = _get_slot_entity_ids(hass, lock.lock.entity_id)
    slot_metadata = _get_slot_metadata(hass, slot_entity_ids)
    ent_reg = er.async_get(hass)

    slots = []
    for slot, code in sorted(data.items()):
        meta = slot_metadata.get(slot)
        slot_ids = slot_entity_ids.get(slot)
        entry_id = slot_ids.config_entry_id if slot_ids else None
        entry_title = None
        in_sync = None
        if entry_id:
            entry = hass.config_entries.async_get_entry(entry_id)
            entry_title = entry.title if entry else None
            in_sync = _get_bool_state(
                hass,
                _in_sync_entity_id(ent_reg, entry_id, slot, lock.lock.entity_id),
            )
        slots.append(
            _serialize_slot(
                slot,
                code,
                reveal=reveal,
                name=meta.name if meta else None,
                managed=slot in managed_slots,
                in_sync=in_sync,
                configured_code=meta.configured_pin if meta else None,
                active=meta.active if meta else None,
                enabled=meta.enabled if meta else None,
                config_entry_id=entry_id,
                config_entry_title=entry_title,
            )
        )

    result: dict[str, Any] = {
        ATTR_LOCK_ENTITY_ID: lock.lock.entity_id,
        ATTR_LOCK_NAME: _get_lock_friendly_name(hass, lock),
        CONF_SLOTS: slots,
    }
    if lock_reachable(hass, lock.lock.entity_id) is False:
        result[ATTR_SYNC_STATUS] = "suspended"
    return result


@websocket_api.websocket_command(
    {
        vol.Required("type"): "lock_code_manager/subscribe_lock_codes",
        vol.Required(ATTR_LOCK_ENTITY_ID): str,
        vol.Optional("reveal", default=False): bool,
    }
)
@websocket_api.async_response
async def subscribe_lock_codes(
    hass: HomeAssistant,
    connection: websocket_api.ActiveConnection,
    msg: dict[str, Any],
) -> None:
    """
    Subscribe to the lock's codes and LCM entity state updates for a lock.

    Triggers updates when:
    - The lock's worker learns of a change (codes on lock)
    - LCM entity states change (enabled, active, name, configured PIN)
    """
    lock_entity_id = msg[ATTR_LOCK_ENTITY_ID]
    reveal = msg["reveal"]
    lock = get_managed_locks(hass).get(lock_entity_id)
    if not lock:
        connection.send_error(
            msg["id"],
            websocket_api.const.ERR_NOT_FOUND,
            f"Lock {lock_entity_id} is not managed by Lock Code Manager",
        )
        return

    @callback
    def _send_update() -> None:
        connection.send_event(
            msg["id"], _serialize_lock_coordinator(hass, lock, reveal=reveal)
        )
        # Re-resolve tracked entities to pick up entities created after
        # subscription was established
        _refresh_state_tracking()

    @callback
    def _on_state_change(event: Event[EventStateChangedData]) -> None:
        """Handle Lock Code Manager entity state changes."""
        old_state = event.data.get("old_state")
        new_state = event.data.get("new_state")

        # Only send update if actual state value changed or entity created/removed
        if old_state is None or new_state is None or old_state.state != new_state.state:
            _send_update()

    # Track Lock Code Manager entity state changes (enabled, active, name, PIN)
    _refresh_state_tracking = _setup_dynamic_state_tracking(
        hass,
        lambda: set(_get_slot_state_entity_ids(hass, lock_entity_id)),
        _on_state_change,
    )
    unsub_state = _refresh_state_tracking()

    # Track what the lock's worker learns (lock code changes).
    unsub_coordinator = async_dispatcher_connect(
        hass, signal_lock_changed(lock_entity_id), _send_update
    )

    def _unsub_all() -> None:
        unsub_coordinator()
        unsub_state()

    connection.subscriptions[msg["id"]] = _unsub_all
    connection.send_result(msg["id"])
    _send_update()


def _get_slot_in_sync_entity_ids(
    hass: HomeAssistant, config_entry: ConfigEntry, slot_num: int
) -> dict[str, str]:
    """
    Get in_sync entity IDs for each lock for a specific slot.

    Returns dict mapping lock_entity_id to in_sync_entity_id.
    """
    ent_reg = er.async_get(hass)
    entry_id = config_entry.entry_id
    lock_entity_ids = get_entry_config(config_entry).locks

    in_sync_map: dict[str, str] = {}
    for lock_entity_id in lock_entity_ids:
        unique_id = f"{entry_id}|{slot_num}|{ATTR_IN_SYNC}|{lock_entity_id}"
        if entity_id := ent_reg.async_get_entity_id(
            BINARY_SENSOR_DOMAIN, DOMAIN, unique_id
        ):
            in_sync_map[lock_entity_id] = entity_id

    return in_sync_map


def _get_condition_entity_data(
    hass: HomeAssistant, condition_entity_id: str | None
) -> dict[str, Any] | None:
    """
    Get condition entity data from entity state.

    Returns dict with entity info and domain-specific data.
    For calendar entities, includes event details (summary, end_time).
    For other entities, includes basic state info.
    """
    if not condition_entity_id:
        return None

