import { CodeDisplayMode } from './types';

export const CODE_SENSOR_KEY = 'code';
export const CODE_EVENT_KEY = 'credential_used';
export const ACTIVE_KEY = 'active';
export const IN_SYNC_KEY = 'in_sync';
// Per-credential in-sync sensors are keyed `<credential>_in_sync`, one per
// credential type the backend manages; `in_sync` is their conjunction. The
// key may be undefined for a registry row that is not shaped like a slot's.
const IN_SYNC_KEY_PATTERN = new RegExp(`^(?:(.+)_)?${IN_SYNC_KEY}$`);
export const isInSyncKey = (key: string | undefined): boolean =>
    typeof key === 'string' && IN_SYNC_KEY_PATTERN.test(key);
// The credential a per-credential in-sync key is for; undefined for the aggregate.
export const inSyncCredential = (key: string): string | undefined =>
    IN_SYNC_KEY_PATTERN.exec(key)?.[1];
// How a credential is named on a card row, keyed by the backend's credential
// type; mirrors CREDENTIAL_LABELS in the backend's const.py.
export const CREDENTIAL_LABELS: Record<string, string> = { password: 'REDACTED', pin: 'PIN' };

// Condition keys
export const CONDITION_CALENDAR = 'calendar';
export const CONDITION_ENTITY = 'condition_entity';
export const CONDITION_KEYS = [CONDITION_CALENDAR, CONDITION_ENTITY];

// Supported condition entity domains
export const CONDITION_ENTITY_DOMAINS = [
    'calendar',
    'binary_sensor',
    'switch',
    'schedule',
    'input_boolean'
] as const;

export type ConditionEntityDomain = (typeof CONDITION_ENTITY_DOMAINS)[number];
export const DIVIDER_CARD = {
    type: 'divider'
};
export const KEY_ORDER = [
    'name',
    'enabled',
    'pin',
    ACTIVE_KEY,
    ...CONDITION_KEYS,
    IN_SYNC_KEY,
    CODE_SENSOR_KEY,
    CODE_EVENT_KEY
];
export const DOMAIN = 'lock_code_manager';

// Strategy defaults (new option names)
export const DEFAULT_CODE_DISPLAY: CodeDisplayMode = 'masked_with_reveal';
export const DEFAULT_SHOW_CODE_SENSORS = true;
export const DEFAULT_SHOW_CONDITIONS = true;
export const DEFAULT_SHOW_LOCK_COUNT = true;
export const DEFAULT_SHOW_PER_CONFIGURATION_LOCK_CARDS = true;
export const DEFAULT_SHOW_LOCK_CARDS = true;
export const DEFAULT_SHOW_LOCK_STATUS = true;
export const DEFAULT_SHOW_LOCK_SYNC = true;
export const DEFAULT_USE_SLOT_CARDS = true;
export const DEFAULT_SHOW_ALL_LOCK_CARDS_VIEW = true;

